#include "app/as7341.h"
#include "uart_harness.h"

void test_pd_driver_on_target() {
    // Initialize UART harness
    UART_Init();

    // Test readiness
    PD_Power_On();
    UART_WaitForReady(1000);
    assert(PD_Get_Ready() == TRUE);

    // Test ID checks
    uint8_t id = PD_Get_ID();
    assert(id == EXPECTED_ID);

    // Test LED control
    PD_LED_On();
    assert(PD_Get_Ready() == TRUE);
    PD_LED_Off();
    assert(PD_Get_Ready() == TRUE);

    // Test threshold configuration
    PD_Set_LowThreshold(0x1234);
    PD_Set_HighThreshold(0x5678);
    assert(PD_Get_LowThreshold() == 0x1234);
    assert(PD_Get_HighThreshold() == 0x5678);

    // Test interrupt handling
    PD_Enable_Interrupt();
    UART_WaitForInterrupt(1000);
    assert(PD_Get_LowInterrupt() == FALSE);
    assert(PD_Get_HighInterrupt() == FALSE);
    PD_Disable_Interrupt();

    // Test measurement validity
    PD_Measurement_Enable();
    UART_WaitForReady(1000);
    assert(PD_Get_Valid() == TRUE);
    uint16_t value = PD_Get_Value();
    assert(value != 0);
    PD_Measurement_Disable();

    // Test impossible thresholds
    PD_Set_LowThreshold(0xFFFF);
    PD_Set_HighThreshold(0x0000);
    UART_WaitForInterrupt(1000);
    assert(PD_Get_Valid() == FALSE);

