    assert(PD_Get_LowThreshold() == DEFAULT_LOW_THRESHOLD);
    assert(PD_Get_HighThreshold() == DEFAULT_HIGH_THRESHOLD);

    // Simulate hardware error
    UART_SimulateError();
    assert(PD_Get_Ready() == FALSE);
}

#include "as7341.h"
#include "uart_harness.h"

void test_pd_driver_on_target() {
    // Initialize UART harness
    UART_Init();

    // Power on the device and wait for readiness
    PD_Power_On();
    UART_WaitForReady(PD_Get_Ready, 1000);

    // Verify device IDs
    assert(PD_Get_AuxID() == EXPECTED_AUX_ID);
    assert(PD_Get_RevID() == EXPECTED_REV_ID);
    assert(PD_Get_ID() == EXPECTED_ID);

    // Test LED control
    PD_Initialize_LED();
    PD_LED_On();
    assert(PD_Measurement_Enabled() == TRUE);
    PD_LED_Off();
    assert(PD_Measurement_Enabled() == FALSE);

    // Set and verify thresholds
    PD_Set_LowThreshold(100);
    PD_Set_HighThreshold(200);
    assert(PD_Get_LowThreshold() == 100);
    assert(PD_Get_HighThreshold() == 200);

    // Enable interrupts and verify
    PD_Enable_Interrupt();
    assert(PD_Interrupt_Enabled() == TRUE);

    // Poll for interrupts
    UART_WaitForInterrupt(PD_Get_LowInterrupt, 1000);
    UART_WaitForInterrupt(PD_Get_HighInterrupt, 1000);

    // Verify measurement validity
    if (PD_Get_Valid()) {
        uint16_t value = PD_Get_Value();
        assert(value > 0);
    } else {
        assert(FALSE); // Fail if not valid
    }

    // Test impossible thresholds
    PD_Set_LowThreshold(300);
    PD_Set_HighThreshold(100);
    UART_WaitForInterrupt(PD_Get_LowInterrupt, 1000);
    UART_WaitForInterrupt(PD_Get_HighInterrupt, 1000);
    assert(PD_Get_Valid() == FALSE);

    // Power off the device
    PD_Power_Off();
}

#include "unity.h"
#include <stdint.h>
#include <stdbool.h>
#include "stm32wb0x_hal.h"
#include "app/as7341.h"

// UART harness setup
#define UART_TIMEOUT 1000
#define POLL_SAMPLES 10

static I2C_HandleTypeDef g_fake_i2c;

void setUp(void) {
    PD_I2c_Init(&g_fake_i2c);
    PD_Power_On();
}

void tearDown(void) {
    // Reset state if needed
}

void test_PD_Readiness_Wait(void) {
    uint32_t start = HAL_GetTick();
    while (!PD_IsReady() && (HAL_GetTick() - start < UART_TIMEOUT)) {
        HAL_Delay(10);
    }
    TEST_ASSERT_TRUE(PD_IsReady());
}

void test_PD_ID_Check(void) {
    uint8_t id = 0;
    TEST_ASSERT_EQUAL(HAL_OK, PD_GetID(&id));
    TEST_ASSERT_EQUAL_UINT8(EXPECTED_ID, id);
}

void test_PD_Thresholds_Configuration(void) {
    TEST_ASSERT_EQUAL(HAL_OK, PD_SetThresholds(0x10, 0x20));
}

void test_PD_Interrupts_Polling(void) {
    PD_EnableInterrupts();
    uint32_t start = HAL_GetTick();
    while (!PD_Get_LowInterrupt() && !PD_Get_HighInterrupt() && (HAL_GetTick() - start < UART_TIMEOUT)) {
        HAL_Delay(10);
    }
    TEST_ASSERT_TRUE(PD_Get_LowInterrupt() || PD_Get_HighInterrupt());
}

void test_PD_Measurement_Validity(void) {
    uint8_t valid = 0;
    TEST_ASSERT_EQUAL(HAL_OK, PD_Get_Valid(&valid));
    TEST_ASSERT_TRUE(valid);
}

void test_PD_Impossible_Thresholds(void) {
    TEST_ASSERT_EQUAL(HAL_OK, PD_SetThresholds(0xFF, 0x00));
    uint32_t start = HAL_GetTick();
    while (PD_Get_Valid() && (HAL_GetTick() - start < UART_TIMEOUT)) {
        HAL_Delay(10);
    }
    TEST_ASSERT_FALSE(PD_Get_Valid());
}

int main(void) {
    UNITY_BEGIN();

    RUN_TEST(test_PD_Readiness_Wait);
    RUN_TEST(test_PD_ID_Check);
    RUN_TEST(test_PD_Thresholds_Configuration);
    RUN_TEST(test_PD_Interrupts_Polling);
    RUN_TEST(test_PD_Measurement_Validity);
    RUN_TEST(test_PD_Impossible_Thresholds);

    return UNITY_END();
}

#include "pd_driver.h"
#include "uart_harness.h"
#include <assert.h>

void test_readiness_wait(void) {
    assert(PD_WaitForReady(1000) == TRUE);
}

void test_id_check(void) {
    uint8_t id = 0;
    assert(PD_ReadID(&id) == TRUE);
    assert(id == EXPECTED_SENSOR_ID);
}

void test_threshold_configuration(void) {
    assert(PD_SetThresholds(LOW_THRESHOLD, HIGH_THRESHOLD) == TRUE);
}

void test_interrupt_polling(void) {
    PD_EnableInterrupts();
    assert(PD_Get_LowInterrupt() == FALSE);
    assert(PD_Get_HighInterrupt() == FALSE);
}

void test_measurement_validity(void) {
    uint16_t measurement = 0;
    assert(PD_Get_Valid() == TRUE);
    assert(PD_ReadMeasurement(&measurement) == TRUE);
}

void test_impossible_thresholds(void) {
    assert(PD_SetThresholds(IMPOSSIBLE_LOW, IMPOSSIBLE_HIGH) == FALSE);
}

void run_on_target_tests(void) {
    test_readiness_wait();
    test_id_check();
    test_threshold_configuration();
    test_interrupt_polling();
    test_measurement_validity();
    test_impossible_thresholds();
}

int main(void) {
    UART_Init();
    run_on_target_tests();
    return 0;
}

#include "Inc/utils/test_harness.h"
#include "PD_driver.h"
#include <stdio.h>

#define TIMEOUT 1000
#define POLL_SAMPLES 10

static TestResult Test_Readiness(void) {
    if (!PD_WaitForReady(TIMEOUT)) {
        return FAIL;
    }
    return PASS;
}

static TestResult Test_IDCheck(void) {
    uint8_t id = 0;
    if (!PD_ReadID(&id) || id != EXPECTED_ID) {
        return FAIL;
    }
    return PASS;
}

static TestResult Test_ThresholdsAndInterrupts(void) {
    PD_SetThresholds(LOW_THRESHOLD, HIGH_THRESHOLD);
    PD_EnableInterrupts();
    for (int i = 0; i < POLL_SAMPLES; i++) {
        if (PD_Get_LowInterrupt() || PD_Get_HighInterrupt()) {
            return FAIL;
        }
    }
    return PASS;
}

static TestResult Test_MeasurementValidity(void) {
    if (!PD_Get_Valid()) {
        return FAIL;
    }
    uint16_t measurement = 0;
    if (!PD_ReadMeasurement(&measurement)) {
        return FAIL;
    }
    return PASS;
}

static TestResult Test_ImpossibleThresholds(void) {
    PD_SetThresholds(IMPOSSIBLE_LOW, IMPOSSIBLE_HIGH);
    PD_EnableInterrupts();
    if (PD_Get_Valid()) {
        return FAIL;
    }
    return PASS;
}

static TestCase test_cases[] = {
    Test_Readiness,
    Test_IDCheck,
    Test_ThresholdsAndInterrupts,
    Test_MeasurementValidity,
    Test_ImpossibleThresholds
};

void RunTests(void) {
    Harness_Loop(test_cases, sizeof(test_cases) / sizeof(TestCase));
}

#include "Inc/utils/serial.h"
#include "PD_driver.h"
#include <stdbool.h>

#define TIMEOUT 5000
#define POLL_SAMPLES 10
#define EXPECTED_SENSOR_ID 0x09
#define LOW_THRESHOLD 100
#define HIGH_THRESHOLD 200
#define IMPOSSIBLE_LOW 0xFFFF
#define IMPOSSIBLE_HIGH 0xFFFF

void test_PD_driver_integration(void) {
    UART_HandleTypeDef huart;
    Serial_Init(&huart);

    // Wait for readiness
    Ready_Wait();

    // Check sensor ID
    uint8_t id = 0;
    PD_ReadID(&id);
    if (id != EXPECTED_SENSOR_ID) {
        Send_Line("ID check failed");
        return;
    }

    // Configure thresholds
    PD_SetThresholds(LOW_THRESHOLD, HIGH_THRESHOLD);

    // Enable interrupts
    PD_EnableInterrupts();

    // Poll for interrupts
    for (int i = 0; i < POLL_SAMPLES; i++) {
        if (PD_Get_LowInterrupt() || PD_Get_HighInterrupt()) {
            Send_Line("Unexpected interrupt");
            return;
        }
    }

    // Check measurement validity
    if (PD_Get_Valid() == TRUE) {
        uint16_t measurement = 0;
        PD_ReadMeasurement(&measurement);
        Send_Line("Measurement valid");
    } else {
        Send_Line("Measurement invalid");
    }

    // Negative test: impossible thresholds
    PD_SetThresholds(IMPOSSIBLE_LOW, IMPOSSIBLE_HIGH);
    if (PD_Get_Valid() == TRUE) {
        Send_Line("Unexpected valid measurement");
    }
}

void test_PD_driver_error_handling(void) {
    // Simulate I2C NACK
    PD_SimulateNACK();
    if (PD_ReadID(NULL) != PD_ERROR_NACK) {
        Send_Line("NACK handling failed");
    }

    // Simulate bus error
    PD_SimulateBusError();
    if (PD_ReadID(NULL) != PD_ERROR_BUS) {
        Send_Line("Bus error handling failed");
    }

    // Simulate timeout
    PD_SimulateTimeout();
    if (PD_ReadID(NULL) != PD_ERROR_TIMEOUT) {
        Send_Line("Timeout handling failed");
    }
}

int main(void) {
    test_PD_driver_integration();
    test_PD_driver_error_handling();
    return 0;
}
